 const profile=weaponDamageProfile(run),stats=attributes(run);set('damage-text',profile.damage.toFixed(1));set('damage-unit',profile.label);set('crit-text',(stats.crit*100).toFixed(1)+'%');set('crit-damage-text','×'+stats.critDamage.toFixed(2));set('challenge-text',activeChallenge(run)?`${CHALLENGES.find(c=>c.id===run.challenge.id).name} · 还需 ${run.challenge.remaining} 场战斗`: '');
