 if(battle.boss&&!battle.boss.dead){document.getElementById('boss-bar').style.display='block';set('boss-name',REGIONS[(run.chapter-1)%REGIONS.length].boss);const warning=battle.bossHazards.find(h=>!h.fired);set('boss-attack-text',warning?`${warning.kind==='bomb'?'延时炸弹':'轨道光束'} · ${Math.max(0,warning.delay-warning.elapsed).toFixed(1)}s`:(battle.boss.attackName||'首领武器就绪'));meter('boss-meter',battle.boss.hp/battle.boss.maxHp*100);}else document.getElementById('boss-bar').style.display='none';
 set('mobile-hp',`${Math.ceil(run.hp)}/${run.maxHp}`);set('mobile-shield',Math.ceil(run.shield));set('mobile-level',run.level);set('mobile-coins',run.coins);set('mobile-damage',profile.damage.toFixed(1));set('mobile-crit',(stats.crit*100).toFixed(0)+'%');set('mobile-critical','×'+stats.critDamage.toFixed(2));set('mobile-weapon',weaponEvolution(run)?.name||weaponLabel(run.weapon));set('mobile-charge',document.getElementById('charge-text')?.textContent||'');set('mobile-challenge',document.getElementById('challenge-text')?.textContent||'');set('touch-dash-status',dashStats(run).charges?`${p.dashCharges}/${dashStats(run).charges}${p.dashCD>0?' · '+p.dashCD.toFixed(1)+'s':''}`:'不可用');const dashButton=document.querySelector('[data-touch="dash"]');if(dashButton)dashButton.disabled=!dashStats(run).charges;const autoButton=document.querySelector('[data-touch="auto"]');if(autoButton){autoButton.setAttribute('aria-pressed',String(autoFire));autoButton.querySelector('span').textContent=autoFire?'开启':'关闭';}
