function modal(html,actions={},options={}){touchControls?.reset();if(state==='battle'&&battle)updateHUD();modalOpen=true;if(battle)battle.player.manualHeld=false;keys.clear();mouseDown=false;modalActions=actions;modalRoot.innerHTML=`<div class="modal-scrim"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(options.label||'作战选择')}">${html}</section></div>`;setTimeout(()=>modalRoot.querySelector('button:not(:disabled)')?.focus(),0);}
function closeModal(){modalRoot.innerHTML='';modalOpen=false;modalActions={};keys.clear();mouseDown=false;if(state==='battle'&&battle&&!autoFire&&(heldManualKey||heldManualPointer)){if(heldManualKey)keys.add('KeyJ');mouseDown=heldManualPointer;battle.player.manualHeld=true;}}
function modalHead(kicker,title,text){return `<div class="modal-head"><div class="kicker">${kicker}</div><h2>${title}</h2><p>${text}</p></div>`;}
function chooseSupply(){return new Promise(resolve=>{
 const available=SUPPLY_REWARDS.filter(x=>supplyRewardAvailable(run,x.id));
 modal(modalHead('VETERAN SUPPLY',`等级提升 · LV.${run.level} · 战备补给`,'当前可用成长已满。选择一份补给，继续积累资源或修复舰体。')+`<div class="choice-grid">${SUPPLY_REWARDS.map(x=>`<button class="choice-card" style="--card-color:var(--cyan)" data-modal="${x.id}" ${supplyRewardAvailable(run,x.id)?'':'disabled'}><div class="choice-icon">${cardArt(x.icon)}</div><h3>${x.name}</h3><p>${x.desc}</p><div class="choice-note">${supplyRewardAvailable(run,x.id)?'选择后继续战斗':x.id==='supply-repair'?'生命与护盾已满':run.recast>=9?'重铸库存已满':'当前没有合法遗物候选'}</div></button>`).join('')}</div>`,Object.fromEntries(available.map(x=>[x.id,()=>{if(!applySupplyReward(run,x.id))return;sound('upgrade');closeModal();resolve();}])));
});}
function chooseUpgrade(){return new Promise(resolve=>{
 let offers=upgradeOffers(run);const show=()=>{
  if(!offers.length){chooseSupply().then(resolve);return;}
  modal(modalHead('SYSTEM UPGRADE',`等级提升 · LV.${run.level}`,isEndless(run)?'无尽基础成长已解除等级上限。选择一项强化，继续作战。':'战斗已暂停。选择一项强化，继续深入星渊。')+`<div class="choice-grid">${offers.map(u=>`<button class="choice-card" style="--card-color:${RARITIES[u.rarity].color}" data-modal="${u.id}"><div class="choice-icon">${cardArt("upgrade-"+u.id)}</div><div class="choice-rarity">${RARITIES[u.rarity].name} / ${u.id.toUpperCase()}</div><h3>${u.name}</h3><p>${upgradeDescription(run,u)}</p><div class="choice-note">当前等级 ${run.upgrades[u.id]||0} / ${Number.isFinite(upgradeLimit(run,u))?upgradeLimit(run,u):"∞ · 无尽成长"}</div></button>`).join('')}</div><div class="modal-actions"><button class="secondary-button" data-modal="reroll" ${run.rerolls<=0?'disabled':''}>刷新候选 · 剩余 ${run.rerolls} 次</button></div>`,Object.fromEntries([...offers.map(u=>[u.id,()=>{applyUpgrade(run,u.id);sound('upgrade');closeModal();resolve();}]),['reroll',()=>{if(run.rerolls>0){run.rerolls--;offers=upgradeOffers(run);show();}}]]));
 };show();
});}
function chooseElement(){return new Promise(resolve=>{
 if(run.elements.length>=3){chooseUpgrade().then(resolve);return;}const options=ELEMENTS.filter(e=>!run.elements.includes(e.id));
 modal(modalHead('ELEMENTAL AWAKENING','元素觉醒','选择一种元素附魔。每局至多三种，双元素将开启独立反应。')+`<div class="choice-grid">${options.map(e=>`<button class="choice-card" style="--card-color:${e.color};min-height:180px" data-modal="${e.id}"><div class="choice-icon">${cardArt("element-"+e.id)}</div><div class="choice-rarity">${e.id.toUpperCase()}</div><h3>${e.label} · ${e.name}</h3><p>${e.desc}</p></button>`).join('')}</div>`,Object.fromEntries(options.map(e=>[e.id,()=>{run.elements.push(e.id);sound('upgrade');closeModal();resolve();}])));
});}
async function processPending(){while(run?.pending.length){const reward=run.pending.shift();if(reward.type==='upgrade')await chooseUpgrade();if(reward.type==='element')await chooseElement();if(reward.type==='challenge-relic')await chooseRelic('elite',`${CHALLENGES.find(c=>c.id===reward.id).name} · 挑战完成`);}}
function relicCard(item,{action=item.id,price=null,sold=false,readonly=false,stack=0,atlas=false,verb="购买",trade=null}={}){
 const missing=run&&SYNERGIES.filter(s=>s.relics.includes(item.id)&&s.relics.filter(id=>!has(run,id)).length===1&&s.elements.every(e=>run.elements.includes(e))&&weaponFits(run,s.weapon));
 const rarity=RARITIES[item.rarity],base=RELIC_EFFECTS[item.id]||item.description,effect=run&&isEndless(run)?base.replace('暴击率最多 40%，暴击倍率最多 2.6。','无尽暴击率可成长至 100%，超出部分转为额外暴击倍率。').replace('总攻速至多两倍','无尽攻速按递减收益继续成长').replace('最终蓄力至少 0.6 秒','前三章最终蓄力至少 0.6 秒，无尽仍可继续加速'):base;
 return `<div class="${atlas?'atlas-card':'choice-card'} relic-card ${sold?'purchased-card':''}" style="--card-color:${rarity.color}" data-relic="${item.id}"><button class="relic-flip" data-relic-flip="${item.id}" aria-label="查看${esc(item.name)}介绍" aria-pressed="false"><span class="relic-inner"><span class="relic-face relic-front" aria-hidden="false"><span class="choice-rarity">${rarity.name} / ${item.id}${stack?' ×'+stack:''}${sold?' / 已购买':''}</span><span class="choice-icon">${cardArt(item.id)}</span><strong>${item.name}</strong><span class="relic-hint">点击翻转 · 查看介绍 ↻</span></span><span class="relic-face relic-back" aria-hidden="true"><span class="choice-rarity">${item.id} / 遗物介绍</span><strong>${item.name}</strong><span class="relic-description">${esc(effect)}</span><span class="relic-restriction">${esc(item.restriction)}</span>${missing?.length?`<span class="choice-note">可激活【${missing[0].name}】</span>`:''}<span class="relic-hint">再次点击 · 返回正面 ↶</span></span></span></button>${trade?`<div class="laboratory-price ${trade.available?'':'unaffordable'}"><span>${laboratoryCostLabel(trade)}</span>${trade.reason?`<small>${esc(trade.reason)}</small>`:''}</div><button class="relic-accept" data-modal="lab-${trade.id}" ${trade.available?'':'disabled'}>支付此代价 · 获得遗物 →</button>`:!readonly?`<button class="relic-accept" data-modal="${action}" ${sold?'disabled':''}>${sold?'已购买':price!==null?(price===0?'免费领取':`◈ ${price} 星币 · ${verb}`):'选择此遗物 →'}</button>`:''}</div>`;
}
function flipCard(event){const button=event.target.closest('[data-relic-flip],[data-card-flip]');if(!button)return false;const name=button.dataset.cardName||RELIC_BY_ID[button.dataset.relicFlip].name,flipped=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(flipped));button.setAttribute('aria-label',`${flipped?'返回':'查看'}${name}${flipped?'正面':'介绍'}`);button.closest('.relic-card').classList.toggle('flipped',flipped);button.querySelector('.relic-front').setAttribute('aria-hidden',String(flipped));button.querySelector('.relic-back').setAttribute('aria-hidden',String(!flipped));return true;}
function recipeCard(item,{kind='synergy',status='',notes=[],offer=false}={}){
 const evolution=kind==='evolution',synergy=evolution?SYNERGIES.find(s=>s.id===item.synergy):item,ids=[...(synergy.relics||[]),...(item.extra?[item.extra]:[])],color=evolution?'var(--gold)':kind==='reaction'?item.color:'var(--cyan)';
 const requirements=[...ids.map(id=>`${run?(has(run,id)?'✓':'○')+' ':''}${id} · ${RELIC_BY_ID[id].name}`),...synergy.elements.map(id=>`${run?(run.elements.includes(id)?'✓':'○')+' ':''}觉醒 ${ELEMENTS.find(e=>e.id===id).name} 元素`),...(synergy.minElements?[`至少 ${synergy.minElements} 种元素`]:[])];
 return `<div class="${offer?'choice-card':'atlas-card'} relic-card recipe-card" style="--card-color:${color}" data-${kind}="${item.id}"><button class="relic-flip" data-card-flip="${item.id}" data-card-name="${esc(item.name)}" aria-label="查看${esc(item.name)}介绍" aria-pressed="false"><span class="relic-inner"><span class="relic-face relic-front" aria-hidden="false"><span class="choice-rarity">${item.id} / ${evolution?'终极进化':kind==='reaction'?'元素反应':'基础共鸣'}</span><span class="choice-icon">${cardArt(item.id)}</span><strong>${item.name}</strong>${status?`<span class="recipe-status">${status}</span>`:''}<span class="relic-hint">点击翻转 · 查看效果与配方 ↻</span></span><span class="relic-face relic-back" aria-hidden="true"><span class="choice-rarity">${item.id} / ${evolution?'进化':kind==='reaction'?'反应':'共鸣'}介绍</span><strong>${item.name}</strong><span class="relic-description">${esc(item.desc)}</span><span class="recipe-requirements">${requirements.map(esc).join('<br>')}</span><span class="relic-restriction">${kind==='reaction'?'双元素自动触发 · 无需遗物':weaponLabel(item.weapon||synergy.weapon)}${evolution?` · 击败 ${item.bosses} 位首领 · 1 枚核心`:''}${item.slot?' · 同武器主形态只能选择一项':''}</span>${notes.length?`<span class="choice-note">${notes.map(esc).join('<br>')}</span>`:''}<span class="relic-hint">再次点击 · 返回正面 ↶</span></span></span></button>${offer?`<button class="relic-accept" data-modal="${item.id}">使用 1 枚核心 · 进化 →</button>`:''}</div>`;
}
function inspectRecipe(kind,id){if(!run||modalOpen||transitioning)return;const item=(kind==='reaction'?ELEMENT_REACTIONS:kind==='evolution'?EVOLUTIONS:SYNERGIES).find(x=>x.id===id);if(!item)return;modal(modalHead('BUILD DETAILS',kind==='reaction'?'双元素反应':kind==='evolution'?'终极进化':'共鸣链路','点击卡片翻转，查看效果、配方与条件。')+`<div class="relic-inspect">${kind==='reaction'?reactionCard(item):recipeCard(item,{kind,status:kind==='evolution'?'已进化':'已激活'})}</div><div class="modal-actions"><button class="primary-button" data-modal="close">关闭介绍</button></div>`,{close:closeModal});}
function inspectRelic(id){if(!run||modalOpen||transitioning||!has(run,id))return;modal(modalHead('RELIC DETAILS','舰载遗物','点击卡片翻转，查看效果和使用条件。')+`<div class="relic-inspect">${relicCard(RELIC_BY_ID[id],{readonly:true,stack:has(run,id),atlas:true})}</div><div class="modal-actions"><button class="primary-button" data-modal="close">关闭介绍</button></div>`,{close:closeModal});}
function chooseRelic(source,title=''){return new Promise(resolve=>{
 const offers=relicOffers(run,source);if(!offers.length){run.coins+=80;resolve();return;}
 const accept=item=>{if(item.rarity==='X'){modal(modalHead('FORBIDDEN CONTRACT','接受禁忌契约？',`${esc(item.name)}：${esc(item.description)}<br>代价会持续整局。你也可以拒绝并获得星币。`)+`<div class="modal-actions"><button class="primary-button gold" data-modal="accept">确认接受</button><button class="secondary-button" data-modal="cancel">返回候选</button></div>`,{accept:()=>finish(item),cancel:show});}else finish(item);};
 const finish=item=>{applyRelic(run,item.id);discover(item.id);sound('upgrade');closeModal();resolve();};
 const show=()=>modal(modalHead('RELIC RECOVERED',title||(source==='boss'?'首领战利品':'深空遗物'),'点击卡片翻转查看介绍，再点击下方按钮选择遗物。满足配方时，共鸣自动激活。')+`<div class="choice-grid">${offers.map(x=>relicCard(x)).join('')}</div><div class="modal-actions"><button class="secondary-button" data-modal="coins">放弃遗物 · 获得 80 星币</button></div>`,Object.fromEntries([...offers.map(x=>[x.id,()=>accept(x)]),['coins',()=>{run.coins+=80;closeModal();resolve();}]]));show();
});}
function discover(id){if(!profile.discovered.includes(id)){profile.discovered.push(id);storage.set('starabyss.profile.v1',profile);}}
function evolutionOffer(){return new Promise(resolve=>{
 if(!run.cores||run.evolutions.length>=2){resolve();return;}const options=eligibleEvolutions(run);
 modal(modalHead('EVOLUTION CORE','进化核心已就绪',options.length?'点击卡片翻转查看效果与配方，再点击下方按钮使用核心进化。':'核心可以保留。下方卡片显示缺少的配方与条件；点击翻面查看，之后可随时从构筑页进化。')+(options.length?`<div class="choice-grid">${options.map(e=>recipeCard(e,{kind:'evolution',status:'配方已就绪',offer:true})).join('')}</div>`:evolutionCards())+`<div class="modal-actions"><button class="secondary-button" data-modal="keep">保留核心</button><button class="secondary-button" data-modal="recast" ${run.recast>7?'disabled':''}>兑换 2 张定向重铸券${run.recast>7?' · 库存空间不足':''}</button></div>`,Object.fromEntries([...options.map(e=>[e.id,()=>{if(!applyEvolution(run,e.id))return;sound('upgrade');closeModal();if(state==='map')saveCheckpoint();resolve();}]),['keep',()=>{closeModal();resolve();}],['recast',()=>{if(!exchangeEvolutionCore(run))return;closeModal();if(state==='map')saveCheckpoint();resolve();}]]));
});}
async function finishBattle(){
 transitioning=true;const finished=battle;finished.restoreChallengeShield();advanceChallenge(run,finished.node);
 await processPending();
 if(finished.node.type==='boss')await chooseRelic('boss');else if(finished.node.type==='elite')await chooseRelic('elite');else if(finished.node.type==='rift'&&finished.riftSuccess)await chooseRelic('rift');else if(finished.node.type==='rift')toast('裂隙挑战未达成 · 保留已获取经验与星币');
 if(finished.node.type==='boss'&&run.cores)await evolutionOffer();
 const won=completeNode(run);transitioning=false;
 if(won){profile.wins++;storage.set('starabyss.profile.v1',profile);saveCheckpoint();showVictory();}
 else if(finished.node.type==='boss')chapterTransition();else showMap();
}
function chapterTransition(){const region=REGIONS[(run.chapter-1)%REGIONS.length];modal(modalHead('SECTOR CLEARED','封锁已突破',`下一站：${region.name}<br>新星图已生成，敌方火力正在增强。`)+`<div class="story-block">你穿过寂静的残骸带。<br>前方的导航灯，正一点点被星云吞没。</div><div class="modal-actions"><button class="primary-button" data-modal="next">前往新星域 →</button></div>`,{next:()=>{closeModal();showMap();}});}
function nodeFinished(){completeNode(run);closeModal();showMap();}
function shop(node){
 let offers=relicOffers(run,'shop',4),sold=new Set(),refreshes=0;
 let free=has(run,'R12')&&run.random()<.25?offers.find(x=>x.rarity==='C')?.id:null;
 const show=()=>{const refreshCost=Math.round(40*Math.pow(2,refreshes)*Math.max(.7,1-.1*has(run,'C11')));const actions={leave:nodeFinished,refresh:()=>{if(refreshes>=3||run.coins<refreshCost)return;run.coins-=refreshCost;refreshes++;offers=relicOffers(run,'shop',4);sold.clear();free=null;show();},recast:()=>{if(!run.recast)return;const candidates=RELICS.filter(x=>legalRelic(run,x,'shop')&&x.tag===run.track);if(!candidates.length){toast('当前追踪方向没有合法候选');return;}const slot=offers.findIndex(x=>!sold.has(x.id));if(slot<0)return;const item=candidates.find(x=>!offers.some(o=>o.id===x.id));if(!item){toast('当前没有可替换的不同候选');return;}run.recast--;offers[slot]=item;show();}};
  for(const item of offers)actions[item.id]=()=>{const price=item.id===free?0:priceFor(run,item);if(sold.has(item.id)||run.coins<price){toast('星币不足');return;}if(!applyRelic(run,item.id)){toast('当前构筑已达到上限或存在互斥');return;}run.coins-=price;sold.add(item.id);discover(item.id);sound('coin');show();};
  modal(modalHead('ORBITAL MARKET','星际商店',`你的星币：<b style="color:var(--gold)">◈ ${run.coins}</b> · 当前追踪：${trackName(run.track)}`)+`<div class="choice-grid shop-grid">${offers.map(x=>relicCard(x,{price:x.id===free?0:priceFor(run,x),sold:sold.has(x.id)})).join('')}</div><div class="modal-actions"><button class="secondary-button" data-modal="refresh" ${refreshes>=3?'disabled':''}>刷新 · ${refreshCost} 星币 (${refreshes}/3)</button><button class="secondary-button" data-modal="recast" ${run.recast<=0?'disabled':''}>定向重铸 · ${run.recast} 张券</button><button class="primary-button" data-modal="leave">离开商店 →</button></div><p class="modal-note">商店不出售禁忌遗物 · 已持有主形态会过滤互斥候选</p>`,actions);
 };show();
}
function repair(){const cost=50,enhance=80;modal(modalHead('MAINTENANCE DOCK','维修站','选择一项服务，或保留资源继续航行。')+`<div class="choice-grid"><button class="choice-card" style="--card-color:#92d6b9" data-modal="heal"><div class="choice-icon">✚</div><h3>修复装甲</h3><p>回复最大生命的 45%，并补满护盾。</p><div class="choice-price">◈ ${cost} 星币</div></button><button class="choice-card" data-modal="enhance"><div class="choice-icon">⬡</div><h3>升级舰体</h3><p>最大生命 +20，同时回复 20 生命。</p><div class="choice-price">◈ ${enhance} 星币</div></button><button class="choice-card" style="--card-color:#869bb0" data-modal="leave"><div class="choice-icon">↗</div><h3>继续航行</h3><p>保留当前资源，不进行维修。</p><div class="choice-note">不消耗星币</div></button></div><p class="modal-note">装甲 ${Math.ceil(run.hp)} / ${run.maxHp} · 星币 ${run.coins}</p>`,{heal:()=>{if(run.coins<cost){toast('维修需要 50 星币');return;}run.coins-=cost;run.hp=Math.min(run.maxHp,run.hp+run.maxHp*.45);run.shield=run.maxShield;nodeFinished();},enhance:()=>{if(run.coins<enhance){toast('强化需要 80 星币');return;}run.coins-=enhance;run.maxHp+=20;run.hp+=20;nodeFinished();},leave:nodeFinished});}
function forge(){const options=Object.keys(run.relics).map(id=>RELIC_BY_ID[id]).filter(x=>x.rarity!=='X'&&legalRelic(run,x,'shop')).slice(0,3);const show=()=>modal(modalHead('RELIC FORGE','深空锻造站',`消耗 100 星币，为一件可叠加遗物增加一层。现有星币 ${run.coins}。`)+(options.length?`<div class="choice-grid">${options.map(x=>relicCard(x,{price:100,verb:"锻造"})).join('')}</div>`:'<div class="story-block">目前没有可升阶的遗物。<br>可购买维修、重铸补给或补全未完成的进化配方。</div>')+`<div class="modal-actions">${!options.length&&(run.upgrades.attack||0)<upgradeLimit(run,UPGRADES.find(x=>x.id==='attack'))?'<button class="secondary-button" data-modal="boost">伤害 +12% · 60 星币</button>':''}<button class="secondary-button" data-modal="support">购买舰载补给 / 配方补全</button><button class="primary-button" data-modal="leave">离开锻造站 →</button></div>`,Object.fromEntries([...options.map(x=>[x.id,()=>{if(run.coins<100){toast('星币不足');return;}if(applyRelic(run,x.id)){run.coins-=100;sound('upgrade');nodeFinished();}}]),['boost',()=>{if(run.coins<60){toast('星币不足');return;}if(!applyUpgrade(run,'attack')){toast('增幅线圈已达上限');return;}run.coins-=60;nodeFinished();}],['support',()=>showSupport(nodeFinished)],['leave',nodeFinished]]));show();}
function showSupport(done=()=>{closeModal();showMap();}){
 const show=()=>{const services=supportServices(run),blueprints=fabricationOffers(run);const actions={leave:done};
  for(const item of services)actions['support-'+item.id]=()=>{if(!buySupport(run,item.id)){toast('星币不足或当前补给已满');return;}sound('coin');show();};
  for(const item of blueprints)actions['blueprint-'+item.id]=()=>{if(!buyBlueprint(run,item.id)){toast('星币不足或配方条件已变化');return;}discover(item.id);sound('upgrade');show();};
  modal(modalHead('SHIPBOARD SUPPORT','舰载补给',`星币 ◈ ${run.coins} · 装甲 ${Math.ceil(run.hp)} / ${run.maxHp} · 刷新 ${run.rerolls} · 重铸券 ${run.recast}`)+`<div class="choice-grid">${services.map(x=>`<button class="choice-card" data-modal="support-${x.id}" ${!x.available||run.coins<x.cost?'disabled':''}><div class="choice-icon">${cardArt(x.icon)}</div><h3>${x.name}</h3><p>${x.desc}</p><div class="choice-price">◈ ${x.cost} 星币</div><div class="choice-note">${!x.available?x.unavailable:run.coins<x.cost?'星币不足':'立即补给'}</div></button>`).join('')}</div>`+(blueprints.length?`<div class="section-line">配方补全 <small>主武器缺件基础价 240–320 星币</small></div><div class="choice-grid shop-grid">${blueprints.map(x=>relicCard(x,{action:'blueprint-'+x.id,price:x.cost,verb:'定向制造'})).join('')}</div>`:'<p class="modal-note">当前没有可制造的进化缺件。禁忌遗物仍需从风险节点获得。</p>')+`<div class="modal-actions"><button class="primary-button" data-modal="leave">返回航行 →</button></div><p class="modal-note">补给不消耗航线层数；每次购买后服务与制造价格增加。库存最多 9 份，不增加伤害或生命上限。舰载补给从第二章开放，锻造站也可提供服务。</p>`,actions);
 };show();
}
function unknownEvent(){const encounter=prepareUnknownEvent(run);if(!encounter)return;const outcome=UNKNOWN_EVENTS.find(e=>e.id===encounter.kind),nodeId=run.current.id;
 const rows=[...Array.from({length:5},()=>UNKNOWN_EVENTS).flat(),outcome];let revealed=false;
 const reveal=()=>{if(revealed||state!=='map'||!modalOpen||run?.current?.id!==nodeId)return;revealed=true;if(encounter.kind==='laboratory')laboratory();else if(encounter.kind==='challenge')challengeEvent();else treasureRoom();};
 modal(modalHead('UNKNOWN TRANSMISSION','未知事件 · 信号解码','禁忌实验室、挑战协议、金币屋——随机触发其中一个。')+`<div class="event-roulette"><div class="event-reel-window"><div class="event-reel-track" style="--reel-stop:-${(rows.length-1)*90}px">${rows.map(e=>`<div class="event-reel-item" style="--event-color:${e.color}"><span>${cardArt(e.icon)}</span><div><strong>${e.name}</strong><small>${e.desc}</small></div></div>`).join('')}</div></div><div class="event-reel-pointer">◇</div><p>正在解析未知信号…</p></div><div class="modal-actions"><button class="secondary-button" data-modal="reveal-event">跳过动画 · 揭晓事件</button></div>`,{'reveal-event':reveal});
 setTimeout(reveal,2200);
}
function laboratoryCostLabel(o){return o.id==='health'?`生命 −${o.cost} · 当前 ${Math.ceil(run.hp)}（不扣上限）`:o.id==='shield'?`最大护盾 −${o.cost} · 当前上限 ${run.maxShield}`:`星币 −${o.cost} · 当前 ${run.coins}`;}
function leaveUnknownEvent(){if(skipUnknownEvent(run))nodeFinished();}
function laboratory(){const offers=laboratoryOffers(run);const finish=o=>{if(!payLaboratory(run,o.id))return;discover(o.relicId);sound('upgrade');nodeFinished();};
 const accept=id=>{const offer=laboratoryOffers(run).find(o=>o.id===id);if(!offer?.available)return;if(offer.item.rarity==='X'){modal(modalHead('FORBIDDEN CONTRACT','接受禁忌契约？',`${esc(offer.item.name)}：${esc(RELIC_EFFECTS[offer.relicId]||offer.item.description)}<br>${laboratoryCostLabel(offer)}。确认后支付这张卡的代价并获得遗物。`)+`<div class="modal-actions"><button class="primary-button gold" data-modal="accept">确认支付并接受</button><button class="secondary-button" data-modal="cancel">返回候选</button></div>`,{accept:()=>finish(offer),cancel:laboratory});}else finish(offer);};
 modal(modalHead('FORBIDDEN LABORATORY','禁忌实验室','三件遗物各自绑定一种代价。点击翻面查看效果；支付下方代价，直接获得对应遗物。生命代价不能致死，最大护盾不能扣成负数。')+`<div class="choice-grid laboratory-grid">${offers.map(o=>o.item?relicCard(o.item,{readonly:true,trade:o}):`<div class="choice-card"><h3>暂无合法遗物</h3><p>当前高品质候选已耗尽。</p><div class="laboratory-price unaffordable">${laboratoryCostLabel(o)}</div></div>`).join('')}</div><div class="modal-actions"><button class="secondary-button" data-modal="leave-event">放弃实验 · 继续航行</button></div>`,{'leave-event':leaveUnknownEvent,...Object.fromEntries(offers.map(o=>['lab-'+o.id,()=>accept(o.id)]))});
}
function challengeEvent(){modal(modalHead('CHALLENGE PROTOCOL','三关挑战协议',activeChallenge(run)?`已有挑战：${CHALLENGES.find(c=>c.id===run.challenge.id).name}，还需 ${run.challenge.remaining} 场战斗。`:'选择一种限制。完成接下来三场战斗后获得一轮遗物三选一，至少一项稀有候选；精英、首领和存活完成的裂隙也计数，安全节点不计数。')+`<div class="choice-grid">${CHALLENGES.map(c=>`<button class="choice-card" style="--card-color:${c.color}" data-modal="challenge-${c.id}" ${challengeAvailable(run,c.id)?'':'disabled'}><div class="choice-icon">${cardArt('challenge-'+c.id)}</div><h3>${c.name}</h3><p>${c.desc}</p><div class="choice-note">三场战斗 · 遗物选择奖励${challengeAvailable(run,c.id)?'':' · 当前不能接受'}</div></button>`).join('')}</div><div class="modal-actions"><button class="secondary-button" data-modal="leave-event">放弃挑战 · 继续航行</button></div>`,{'leave-event':leaveUnknownEvent,...Object.fromEntries(CHALLENGES.map(c=>['challenge-'+c.id,()=>{if(!startChallenge(run,c.id))return;nodeFinished();}]))});}

function treasureRoom(){const amount=treasureReward(run);modal(modalHead('ABANDONED TREASURY','金币屋','一座无人货舱隐藏在星云中。回收舰载星币，无需支付费用。')+`<div class="treasure-scene"><div class="treasure-orbit"></div><div class="treasure-vault">◈</div><div class="treasure-amount">+${amount}<small>星币</small></div><p>可用于遗物、维修、锻造和舰载补给</p></div><div class="modal-actions"><button class="primary-button gold" data-modal="claim-treasure">领取 ${amount} 星币 · 继续航行 →</button></div>`,{'claim-treasure':()=>{const claimed=claimTreasure(run);if(!claimed)return;sound('coin');nodeFinished();}});}
function chooseNode(id){if(state!=='map'||modalOpen)return;const node=selectNode(run,id);if(!node)return;if(['combat','elite','boss','rift'].includes(node.type))showBattle(node);else if(node.type==='shop')shop(node);else if(node.type==='repair')repair();else if(node.type==='forge')forge();else unknownEvent();}
function trackName(id){return {beam:'射线构筑',attack:'火力暴击',drone:'僚机编队',survival:'护盾生存',element:'元素反应',economy:'经济成长'}[id]||id;}
function evolutionCards({allowEvolution=false}={}){const eligible=new Set(eligibleEvolutions(run).map(e=>e.id));return `<div class="section-line">终极进化 <small>核心 ${run.cores} · 已进化 ${run.evolutions.length} / 2 · 已击败首领 ${run.bosses}</small></div><div class="recipe-grid">${evolutionProgress(run).map(e=>{const requirements=[...e.missingRelics.map(id=>'缺少 '+RELIC_BY_ID[id].name),...e.missingElements.map(id=>'需要 '+ELEMENTS.find(x=>x.id===id).name),...(e.missingElementCount?['需觉醒 '+e.missingElementCount+' 种元素']:[]),...(run.bosses<e.bosses?[`还需击败 ${e.bosses-run.bosses} 位首领（${run.bosses} / ${e.bosses}）`]:[])];const status=e.selected?'已进化':e.conflicting?'与当前形态冲突':run.evolutions.length>=2?'本局进化次数已满':requirements.length?'配方未完成':run.cores?'可使用核心进化':'配方已就绪 · 等待核心';return recipeCard(e,{kind:'evolution',status,notes:requirements,offer:allowEvolution&&run.cores>0&&eligible.has(e.id)});}).join('')}</div>`;}

function reactionCard(q){return recipeCard(q,{kind:'reaction',status:q.elements.map(id=>ELEMENTS.find(e=>e.id===id).name).join(' + '),notes:[`基础冷却 ${q.cd} 秒`,...Object.entries(q.min||{}).map(([id,n])=>`${ELEMENTS.find(e=>e.id===id).name}至少 ${n} 层`),'叠层增幅最多 +50%；首领反应每秒最多为最大生命的 2%']});}
function elementReactionBuild(){const reactions=activeElementReactions(run);return `<div class="section-line">双元素反应 <small>已解锁 ${reactions.length} 组 · 点击翻面查看作用与触发条件</small></div><div class="recipe-grid build-reactions">${reactions.map(reactionCard).join('')||'<p class="subtitle">觉醒至少两种元素后，在此查看组合效果。</p>'}</div>`;}
function showBuild(){const returnTo=()=>{closeModal();if(state==='battle')updateHUD();};const sy=activeSynergies(run);const active=sy.map(s=>s.id);const almost=SYNERGIES.filter(s=>!active.includes(s.id)&&s.relics.some(id=>has(run,id))&&s.elements.every(e=>run.elements.includes(e))&&weaponFits(run,s.weapon));
 modal(modalHead('BUILD OVERVIEW','舰载构筑',`${run.frame.name} / ${WEAPONS.find(w=>w.id===run.weapon).name} · 火力 ×${attributes(run).attack.toFixed(2)} · 暴击 ${Math.round(attributes(run).crit*100)}% / ×${attributes(run).critDamage.toFixed(2)} · 闪避 ${dashStats(run).charges} 段 × ${dashStats(run).duration.toFixed(2)} 秒 · 减伤 ${Math.round(dashStats(run).reduction*100)}% · ${run.elements.map(id=>ELEMENTS.find(e=>e.id===id).name).join(' + ')||'尚未觉醒元素'}`)+`<div class="atlas-toolbar">${['beam','attack','drone','survival','element','economy'].map(id=>`<button class="pill ${run.track===id?'selected':''}" data-modal="track-${id}">${trackName(id)}</button>`).join('')}</div><div class="small-label">追踪方向影响合法候选权重，不保证获得指定遗物。</div><div class="recipe-grid">${sy.map(s=>recipeCard(s,{status:'共鸣已激活'})).join('')}${almost.map(s=>recipeCard(s,{status:'配方未完成'})).join('')}</div>${elementReactionBuild()}${evolutionCards({allowEvolution:true})}<div class="atlas-grid" style="margin-top:20px">${Object.entries(run.relics).map(([id,n])=>relicCard(RELIC_BY_ID[id],{readonly:true,stack:n,atlas:true})).join('')||'<p class="subtitle">尚无遗物，前往精英战斗或商店寻找构筑组件。</p>'}</div><div class="modal-actions"><button class="primary-button" data-modal="close">返回航行 →</button>${run.cores&&eligibleEvolutions(run).length?'<button class="secondary-button" data-modal="evolve">使用进化核心</button>':''}<button class="secondary-button" data-modal="export">导出作战日志</button></div>`,{close:returnTo,export:exportLog,...Object.fromEntries(eligibleEvolutions(run).map(e=>[e.id,()=>{if(!applyEvolution(run,e.id))return;sound('upgrade');if(state==='map')saveCheckpoint();showBuild();}])),evolve:async()=>{closeModal();await evolutionOffer();showBuild();},...Object.fromEntries(['beam','attack','drone','survival','element','economy'].map(id=>['track-'+id,()=>{run.track=id;showBuild();}]))});
}
function showAtlas(filter='all'){
 setPage('atlas','遗物档案 / RELIC ARCHIVE');const items=filter==='all'?RELICS:['recipes','elemental'].includes(filter)?[]:RELICS.filter(x=>x.rarity===filter);
 screen.innerHTML=header('KNOWLEDGE IS FIREPOWER','遗物档案',`${RELICS.length} 件设计遗物 · ${SYNERGIES.length} 组共鸣配方 · ${EVOLUTIONS.length} 项终极进化 · ${ELEMENT_REACTIONS.length} 种元素反应`,`<span class="tag">已发现 ${profile.discovered.length} / ${RELICS.length}</span>`)+`<div class="atlas-toolbar">${[['all','全部遗物'],...Object.entries(RARITIES).map(([id,r])=>[id,r.name]),['recipes','共鸣与进化'],['elemental','双元素反应']].map(([id,label])=>`<button class="pill ${filter===id?'selected':''}" data-action="filter" data-id="${id}">${label}</button>`).join('')}</div><div class="subtitle">遗物、共鸣与进化均可点击翻转，查看当前效果、配方与使用条件。</div>`+(filter==='elemental'?`<div class="recipe-grid">${ELEMENT_REACTIONS.map(q=>recipeCard(q,{kind:'reaction',status:q.elements.map(id=>ELEMENTS.find(e=>e.id===id).name).join(' + '),notes:[`基础冷却 ${q.cd} 秒`,...Object.entries(q.min||{}).map(([id,n])=>`${ELEMENTS.find(e=>e.id===id).name}至少 ${n} 层`),'叠层增幅最多 +50%；首领反应每秒最多为最大生命的 2%']})).join('')}</div>`:filter==='recipes'?`<div class="recipe-grid">${SYNERGIES.map(s=>recipeCard(s)).join('')}${EVOLUTIONS.map(e=>recipeCard(e,{kind:'evolution'})).join('')}</div>`:`<div class="atlas-grid" style="margin-top:20px">${items.map(r=>relicCard(r,{readonly:true,atlas:true})).join('')}</div>`)+`<div class="modal-actions"><button class="secondary-button" data-action="return">返回${run?'航线':'机库'} →</button></div>`;
}
function showGuide(){setPage('guide','飞行手册 / FLIGHT MANUAL');screen.innerHTML=header('YOUR FIRST FLIGHT','飞行手册','读懂航线，驾驭火力。每一次出击，都是新的构筑。')+`<div class="guide-grid"><div class="guide-panel"><h2>01 / 舰载操作</h2><p>手机：左侧摇杆或拖动战场移动，右侧射击键按住蓄力、松开发射；按住射击会关闭自动火力，可随时点“自动”重新开启。闪避每点一次消耗一段。棱镜装备后出现左右调角键。多指可同时移动、射击和闪避；旋转屏幕或切换后台会自动暂停。构筑、暂停及所有卡片均支持触屏。</p><p><kbd>W A S D</kbd> 或方向键移动<br><kbd>空格</kbd> 闪避：苍穹隼一段 0.65 秒 / 8 秒恢复；幽灵翼两段各 0.35 秒 / 逐段 6 秒恢复；泰坦卫一段 0.9 秒 / 9 秒恢复。每按一次消耗一段，长按不会连续消耗<br><kbd>J</kbd> 或鼠标左键射击，射线长按蓄力后松开；射线与轨道炮均可提前释放，蓄满可持续保持<br>持有万象棱镜时，手动 ←/→ 调角，WASD 移动，淡色线预览路径；自动沿用手动角度<br><kbd>F</kbd> 开关自动火力，默认开启<br><kbd>M</kbd> 切换鼠标驾驶<br><kbd>ESC</kbd> 暂停，<kbd>F11</kbd> 全屏<br>支持手柄左摇杆、A 闪避、RT 射击、START 暂停</p><p>火焰、冰晶、电弧、毒雾、辉光和暗蚀各有独立标记与弹道颜色；敌舰下方显示当前叠层/上限；叠层越高，灼烧、毒素、雷链、冰与光的主武器增伤、暗的目标易伤与双元素反应越强，刷新后的持续时间也越长。火基础 5 层（余烬最多提高到 9）、冰 6、雷 6、毒 8、光与暗基础各 5（噬影结晶可将暗升至 7）；持续时间最多为火 8 秒、冰/雷/光/暗 5 秒、毒 9 秒。双元素反应的叠层加成最多 +50%，首领反应伤害仍受每秒预算限制。全部 15 种双元素搭配都有自动反应，档案可翻转查看配方与作用。暗使目标受到所有来源伤害增加，光提高主武器直接伤害；三种暗遗物分别强化易伤、烙印脉冲和叠层。元素反应会显示名称。敌弹始终保持橙红色。机体中心的白点是受击判定点。五秒未受击，护盾会逐渐恢复。</p></div><div class="guide-panel"><h2>02 / 星图与战斗</h2><p>一局包含 3 章，每章 12 层，第 12 层固定首领。只可沿连线选择节点，前方两层完整可见。</p><p>第一章前三层只出现战斗与未知事件，积累资源后再出现商店、维修和锻造。未知事件通过滚动信号揭晓禁忌实验室、挑战协议或金币屋之一；金币屋免费领取星币，奖励随章节和楼层提高，不再是独立星图节点；普通战斗提供经验与星币；精英保证至少一项稀有或更高候选；裂隙需在 45 秒内击杀 18 架敌舰。首领在 65% 与 30% 生命进入新阶段，轮换扇形瞄射、螺旋弹幕、通道封锁、延时炸弹和轨道光束。炸弹提前至少 1.8 秒标出固定落点，光束预警 1.6 秒；走出橙色范围或闪避即可躲避。</p><p>探索模式降低敌人生命与伤害，适合熟悉构筑。首次通关后可继续无尽星图。第四章起，伤害、攻速、生命、护盾、移动、暴击、弹速与元素精通解除升级等级上限；攻速和移动采用递减收益，暴击率可达 100%，超出部分转为暴击倍率。射线形态、印记、遗物和进化保留各自上限。无尽敌舰与首领的生命、护甲、伤害和射速随章节增强，生命采用二次成长曲线。禁忌实验室的三件遗物分别绑定当前生命 20—28、最大护盾 10—18、星币 111/222/333/444/555/666 中的随机代价，支付才获得对应遗物；生命支付后必须大于 0、护盾上限至少为 0，资源不足不能选择；三关挑战可禁用闪避、暂停护盾或降低主武器伤害，完成后获得遗物选择，安全房不计数。战斗左侧实时显示单枚主弹（射线单跳）基础伤害、暴击率与暴击伤害倍率。</p></div><div class="guide-panel"><h2>03 / 构筑与共鸣</h2><p>普通升级强化属性；暴击聚能把实际暴击率转为主武器增伤，前三章三层最多 +60%，无尽时实际暴击率提高会继续加强转化（仍计入条件增伤总上限 +200%）。轨道炮基础弹速降至 360、命中半径增至 12，蚀刻弹道升级会留下持续 1.5 秒、最多六跳的路径印记。相位延展器增加闪避时间，锚定装甲以一段闪避换取 35% 减伤，单段机体装备后无法闪避。前三章当前可用成长全满后改为选择 120 星币、维修或定向重铸补给。第二章起星图开放舰载补给，可付费修复、补充刷新和重铸券，以及定向制造合法进化缺件。遗物来自精英、首领、商店和事件。10 级、第三个首领、30 级各提供一次元素选择，最多三种。</p><p>遗物、共鸣、进化和双元素反应卡都可点击翻转查看效果与配方；对局构筑页显示本局已解锁的元素组合，战斗右侧可直接点击查看并暂停作战；战斗右侧的遗物与已激活构筑也可点击查看。两件遗物满足配方与武器/元素条件时，自动激活共鸣。第一、第三、第六、第九个首领掉落核心；星蚀射线有四条专属主形态进化，四种弹丸武器各有两条路线；全部主武器进化击败第一位首领后开放，统一需要两件对应遗物与一枚核心，不再额外要求传说/禁忌组件。首领奖励有机会补齐当前武器缺件，定向制造的主武器缺件基础价 240–320 星币。构筑页显示所需遗物，每局最多两次进化，同武器主形态只能选择一项。</p><p>主射线形态互斥，未觉醒元素的专属遗物不进入候选池。禁忌遗物只在明确风险来源出现，必须二次确认。</p></div><div class="guide-panel"><h2>04 / 存档与素材</h2><p>完成节点后自动保存检查点；关闭后可从机库继续。未完成的战斗/交易会回到进入前的检查点。存档保存在本机，不提供云同步。</p><p>音效使用 Kenney 的 CC0 免费素材，经 Python Arcade 官方资源仓库获取；旧版图像仍保留在素材包中。新版舰船、专属卡面、星云、首领与武器特效均为原创程序图形。</p><p>首版重点验证星图与战斗循环。复杂反射共鸣、储能、手柄震动、商店锁定/出售和完整平衡模拟仍需后续完善，详见 DEVELOPMENT.md。主流程数值采用 v1.4 节点制与 v1.3 经济。</p></div></div><div class="modal-actions"><button class="secondary-button" data-action="return">返回${run?'航线':'机库'} →</button></div>`;}
function pause(){if(state!=='battle'||modalOpen||transitioning)return;modal(modalHead('FLIGHT SUSPENDED','作战暂停','喘息片刻。星渊会等你回来。')+`<div class="paused-label">Ⅱ</div><div class="modal-actions"><button class="primary-button" data-modal="resume">继续战斗 →</button><button class="secondary-button" data-modal="build">查看构筑</button><button class="secondary-button" data-modal="exit">返回机库</button></div><p class="modal-note">返回机库会保留上一个完成节点的检查点。</p>`,{resume:closeModal,build:showBuild,exit:()=>{closeModal();battle=null;run=null;showHangar();}});}
const sourceLabels={PRIMARY:'主武器',BEAM_TICK:'射线伤害',REFLECT:'棱镜折射',BRANCH:'分支射线',CHAIN:'连锁雷电',SPLIT:'裂变弹片',ECHO:'永恒回响',DOT:'持续伤害',ELEMENT_REACTION:'元素反应',SUMMON:'僚机召唤',SINGULARITY:'奇点坍缩',FINISHER:'终结脉冲',EVOLUTION_BLAST:'进化爆破',EVOLUTION_FIELD:'引力场',RAIL_MARK:'弹道印记',EVOLUTION_SWARM:'蜂群子弹',DARK_PULSE:'蚀影脉冲'};
function resultsHTML(won){const total=Object.values(run.damage).reduce((a,b)=>a+b,0)||1;return modalHead(won?'MAIN CAMPAIGN CLEARED':'FLIGHT REPORT',won?'星渊，尚无尽头':'本次航行结束',won?'你已突破三大星域。更深处的信号，仍在等待回应。':`失去联络：${run.lastDeath||'未知信号'} · ${REGIONS[(run.chapter-1)%REGIONS.length].name} / 第 ${run.floor+1} 层`)+`<div class="results"><div class="result-stat"><b>${run.score.toLocaleString()}</b><small>总分数</small></div><div class="result-stat"><b>${run.kills}</b><small>击落敌机</small></div><div class="result-stat"><b>${Math.floor(run.time/60)}:${String(Math.floor(run.time%60)).padStart(2,'0')}</b><small>作战时间</small></div><div class="result-stat"><b>${Object.keys(run.relics).length}</b><small>构筑遗物</small></div></div><div class="damage-chart">${Object.entries(run.damage).sort((a,b)=>b[1]-a[1]).map(([key,value])=>`<div class="damage-row"><span>${sourceLabels[key]||key}</span><div class="meter"><i style="width:${value/total*100}%"></i></div><span>${Math.round(value/total*100)}%</span></div>`).join('')}</div><p class="modal-note">种子 ${esc(run.seed)} · 最高连锁 ${run.stats.maxChain} · 生命承伤 ${Math.round(run.stats.damageTaken)}<br>${activeSynergies(run).map(s=>s.name).join(' / ')||'未激活共鸣'}</p>`;}
function recordResult(){profile.runs++;profile.best=Math.max(profile.best,run.score);profile.deepest=Math.max(profile.deepest,run.chapter*12+run.floor);storage.set('starabyss.profile.v1',profile);}
function showDefeat(){transitioning=true;recordResult();storage.remove('starabyss.run.v1');modal(resultsHTML(false)+`<div class="modal-actions"><button class="primary-button" data-modal="hangar">返回机库 →</button><button class="secondary-button" data-modal="export">导出作战日志</button></div>`,{hangar:()=>{closeModal();run=null;battle=null;transitioning=false;showHangar();},export:exportLog});}
function showVictory(){recordResult();battle=null;modal(resultsHTML(true)+`<div class="modal-actions"><button class="primary-button gold" data-modal="endless">进入无尽星渊 ↗</button><button class="secondary-button" data-modal="hangar">完成航行</button><button class="secondary-button" data-modal="export">导出作战日志</button></div>`,{endless:()=>{closeModal();showMap();},hangar:()=>{storage.remove('starabyss.run.v1');closeModal();run=null;showHangar();},export:exportLog});}
function exportLog(){if(!run)return;const data={seed:run.seed,chapter:run.chapter,floor:run.floor,weapon:run.weapon,relics:run.relics,elements:run.elements,evolutions:run.evolutions,damage:run.damage,stats:run.stats,routes:run.path,events:run.logs,damageEvents:battle?.damageLog||[]};const text=JSON.stringify(data,null,2);if(window.NativeBridge?.shareText){window.NativeBridge.shareText(text,'星渊作战日志');return;}if(window.webkit?.messageHandlers?.shareText){window.webkit.messageHandlers.shareText.postMessage({text});return;}const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));link.download=`star-abyss-${run.seed.replace(/[^a-zA-Z0-9_-]/g,'_')}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('作战日志已导出');}
async function startRun(){const seed=document.getElementById('run-seed')?.value.trim()||Date.now().toString(36);const begin=()=>{closeModal();profile.frame=selectedFrame;profile.weapon=selectedWeapon;storage.set('starabyss.profile.v1',profile);run=createRun({frame:selectedFrame,weapon:selectedWeapon,difficulty,seed});autoFire=true;logLines=[];transitioning=false;ambient();showMap();};if(storage.get('starabyss.run.v1',null)){modal(modalHead('NEW FLIGHT','开始新的航行？','新出击将替换已有检查点。机库记录与遗物发现会保留。')+`<div class="modal-actions"><button class="primary-button" data-modal="start">开始新航行</button><button class="secondary-button" data-modal="cancel">取消</button></div>`,{start:begin,cancel:closeModal});}else begin();}
const actions={'preview-replay':()=>weaponPreview?.reset(),'inspect-relic':inspectRelic,'inspect-synergy':id=>inspectRecipe('synergy',id),'inspect-evolution':id=>inspectRecipe('evolution',id),'inspect-reaction':id=>inspectRecipe('reaction',id),frame:id=>{selectedFrame=id;showHangar();},weapon:id=>{selectedWeapon=id;showHangar();},difficulty:id=>{difficulty=id;showHangar();},start:startRun,continue:()=>{if(loadCheckpoint()){transitioning=false;showMap();}else toast('未找到有效检查点');},node:chooseNode,filter:showAtlas,return:()=>run?showMap():showHangar(),build:showBuild,pause,support:()=>{if(state==='map'&&run.chapter>=2)showSupport();},'save-exit':()=>{saveCheckpoint();run=null;showHangar();}};
screen.addEventListener('click',event=>{if(flipCard(event))return;const target=event.target.closest('[data-action]');if(target&&!target.disabled)actions[target.dataset.action]?.(target.dataset.id);});screen.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('g[data-action]')){event.preventDefault();chooseNode(event.target.dataset.id);}});
modalRoot.addEventListener('click',event=>{if(flipCard(event))return;const target=event.target.closest('[data-modal]');if(target&&!target.disabled)modalActions[target.dataset.modal]?.();});
modalRoot.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const buttons=[...modalRoot.querySelectorAll('button:not(:disabled),a,input')];if(!buttons.length)return;const index=buttons.indexOf(document.activeElement);if(event.shiftKey&&index===0){event.preventDefault();buttons.at(-1).focus();}else if(!event.shiftKey&&index===buttons.length-1){event.preventDefault();buttons[0].focus();}});
document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>{if(state==='battle'){pause();return;}if(modalOpen)return;const page=button.dataset.page;if(page==='hangar'){if(run)saveCheckpoint();run=null;showHangar();}if(page==='atlas')showAtlas();if(page==='guide')showGuide();}));document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();if(state==='battle')pause();else if(!modalOpen){if(run)saveCheckpoint();run=null;showHangar();}});
document.getElementById('sound-toggle').addEventListener('click',()=>{profile.sound=!profile.sound;storage.set('starabyss.profile.v1',profile);document.getElementById('sound-toggle').style.opacity=profile.sound?'1':'.4';if(audioContext)profile.sound?audioContext.resume():audioContext.suspend();else ambient();toast(profile.sound?'音效已开启':'音效已静音');});
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('当前窗口不支持全屏，请使用桌面版或浏览器全屏');}}
document.getElementById('fullscreen-toggle').addEventListener('click',fullscreen);
addEventListener('keydown',event=>{
 if(event.target.matches('input,textarea,select'))return;
 if(state==='battle'&&event.code==='KeyJ')heldManualKey=true;
 if(event.code==='F11'){event.preventDefault();fullscreen();return;}
 if(event.code==='Escape'){if(state==='battle'&&!transitioning){if(modalOpen&&modalActions.resume)closeModal();else if(!modalOpen)pause();}return;}
 if(state!=='battle'||modalOpen)return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyJ'].includes(event.code))event.preventDefault();if(event.repeat)return;
 keys.add(event.code);if(event.code==='KeyF'){autoFire=!autoFire;toast(autoFire?'自动火力已启用':'手动火力 · 长按 J，松开释放');}if(event.code==='KeyM'){pointerMode=!pointerMode;toast(pointerMode?'鼠标驾驶已启用':'键盘驾驶已启用');}
});addEventListener('pointerup',event=>{if(event.pointerType==='touch')return;heldManualPointer=false;mouseDown=false;});addEventListener('keyup',event=>{keys.delete(event.code);if(event.code==='KeyJ')heldManualKey=false;});addEventListener('blur',()=>{touchControls?.cancel();keys.clear();heldManualKey=false;heldManualPointer=false;mouseDown=false;if(state==='battle'&&!modalOpen)pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='battle'){touchControls?.cancel();heldManualKey=false;heldManualPointer=false;pause();}});
let gamepadPause=false;
function input(){const prism=run?.weapon==='beam'&&has(run,'E03'),aim=prism?Number(keys.has('ArrowRight'))-Number(keys.has('ArrowLeft')):0;let x=(keys.has('KeyD')||!prism&&keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||!prism&&keys.has('ArrowLeft')?1:0),y=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0),fire=keys.has('KeyJ')||mouseDown,dash=keys.has('Space');const pad=navigator.getGamepads?.()?.[0];if(pad){x+=Math.abs(pad.axes[0])>.15?pad.axes[0]:0;y+=Math.abs(pad.axes[1])>.15?pad.axes[1]:0;fire||=pad.buttons[7]?.pressed;dash||=pad.buttons[0]?.pressed;const pressed=pad.buttons[9]?.pressed;if(pressed&&!gamepadPause)pause();gamepadPause=pressed;}
 const touch=touchControls?.read();return{x:x+(touch?.x||0),y:y+(touch?.y||0),fire:fire||touch?.fire,dash:dash||touch?.dash,dashPressed:touch?.dashPressed,aim:aim+(touch?.aim||0),auto:autoFire,pointer:touch?.pointer||(pointerMode?pointer:null)};
}
function handleEvents(){if(!run)return;for(const event of run.events.splice(0)){if(['shoot','beam','kill','hurt'].includes(event.type))sound(event.type);if(event.type==='synergy'){toast(`共鸣激活 · ${event.name}`);log(`共鸣在线：${event.name}`);}if(event.type==='evolution'){toast(`终极进化 · ${event.name}`);log(`武器进化：${event.name}`);}if(event.type==='boss-attack')log(`首领攻击：${event.name}`);if(event.type==='reaction')log(`元素反应：${event.name}`);if(event.type==='wave')log(`第 ${event.wave} 编队接敌`);if(event.type==='revive'){toast('紧急跃迁 · 致命伤害已规避');log('紧急跃迁已触发');}}}
let layoutFrame=0,lastLandscape=innerWidth>innerHeight;function mobileLayout(){const touch=touchDevice();document.body.classList.toggle('touch-ui',touch);document.body.classList.toggle('mobile-ui',touch);document.documentElement.style.setProperty('--app-height',(visualViewport?.height||innerHeight)+'px');document.documentElement.style.setProperty('--app-width',(visualViewport?.width||innerWidth)+'px');const canvas=document.getElementById('battle-canvas');if(canvas)ctx=prepareCanvas(canvas);}
function resizeMobile(){if(layoutFrame)return;layoutFrame=requestAnimationFrame(()=>{layoutFrame=0;const landscape=innerWidth>innerHeight;if(touchDevice()&&landscape!==lastLandscape&&state==='battle'){touchControls?.cancel();pause();}lastLandscape=landscape;mobileLayout();});}
addEventListener('resize',resizeMobile);visualViewport?.addEventListener('resize',resizeMobile);addEventListener('orientationchange',()=>{touchControls?.cancel();if(state==='battle')pause();resizeMobile();});mobileLayout();
window.starAbyssNativeBack=()=>{if(state==='battle'){if(modalOpen&&modalActions.resume)closeModal();else if(!modalOpen)pause();return true;}if(modalOpen)return true;if(run)saveCheckpoint();return false;};
addEventListener('pointerdown',event=>{if(event.pointerType==='touch'&&audioContext?.state==='suspended')audioContext.resume().catch(()=>{});},{passive:true});
const background=initCosmos(document.getElementById('cosmos'));let last=performance.now(),accumulator=0,hudTimer=0;
function frame(now){const elapsed=Math.min(.1,(now-last)/1000);last=now;if(!(touchDevice()&&state==='battle'))background(now/1000);if(state==='hangar'){drawHangarShips(now/1000);weaponPreview?.update(elapsed);}
 if(state==='battle'&&battle&&ctx){
  if(!modalOpen&&!transitioning){accumulator+=elapsed;let i=0;while(accumulator>=STEP&&i++<12){battle.update(STEP,input());accumulator-=STEP;if(battle.over||battle.done||run.pending.length)break;}handleEvents();
   if(battle.over)showDefeat();else if(battle.done)finishBattle();else if(run.pending.length){transitioning=true;processPending().then(()=>{transitioning=false;});}
  }else accumulator=0;
  renderBattle(ctx,battle);hudTimer+=elapsed;if(hudTimer>.1){hudTimer=0;updateHUD();}
 }
 requestAnimationFrame(frame);
}
assetsReady.then(()=>{showHangar();requestAnimationFrame(frame);});
